-- Converted: GRANT SELECT, INSERT ON TABLE sales.payment TO operator -> GRANT SELECT, INSERT ON TABLE SALES.PAYMENT TO ROLE OPERATOR.
-- Reason: Snowflake grants object privileges to roles (TO ROLE). The privileges stay specific (no ALL, no PUBLIC), and the table name comes from the naming map.
GRANT SELECT, INSERT ON TABLE SALES.PAYMENT TO ROLE OPERATOR;

-- Converted: GRANT SELECT ON TABLE sales.audit_log TO auditor -> GRANT SELECT ON TABLE SALES.AUDIT_LOG TO ROLE AUDITOR.
-- Reason: Snowflake grants object privileges to roles. The read-only privilege stays narrowly scoped, and the table name comes from the naming map.
GRANT SELECT ON TABLE SALES.AUDIT_LOG TO ROLE AUDITOR;

-- Converted: GRANT EXECUTE PROCEDURE ON sales.add_payment TO operator -> GRANT USAGE ON PROCEDURE SALES.ADD_PAYMENT(<argument types>) TO ROLE OPERATOR, run through an anonymous Snowflake Scripting block that reads the argument signature from SHOW USER PROCEDURES.
-- Reason: Snowflake controls who can call a procedure through the USAGE privilege, and the GRANT must name the procedure's full argument-type signature. The batch does not include the converted ADD_PAYMENT signature, so the block resolves it from the catalog instead of guessing it. Square brackets that SHOW uses to mark optional (DEFAULT) arguments are removed.
EXECUTE IMMEDIATE
$$
DECLARE
  grant_count INTEGER DEFAULT 0;
  no_procedure EXCEPTION (-20001, 'Procedure SALES.ADD_PAYMENT not found; deploy it before granting USAGE.');
  sigs RESULTSET;
BEGIN
  SHOW USER PROCEDURES LIKE 'ADD_PAYMENT' IN SCHEMA SALES;
  sigs := (
    SELECT REPLACE(REPLACE(SPLIT_PART("arguments", ' RETURN ', 1), '[', ''), ']', '') AS proc_signature
    FROM TABLE(RESULT_SCAN(LAST_QUERY_ID()))
  );
  FOR rec IN sigs DO
    -- Converted: The Teradata EXECUTE PROCEDURE privilege -> Snowflake USAGE ON PROCEDURE for the resolved signature.
    -- Reason: Identifiers cannot be bind variables, so the catalog-derived signature (not user input) is concatenated into the statement.
    EXECUTE IMMEDIATE 'GRANT USAGE ON PROCEDURE SALES.' || rec.proc_signature || ' TO ROLE OPERATOR';
    grant_count := grant_count + 1;
  END FOR;
  IF (grant_count = 0) THEN
    RAISE no_procedure;
  END IF;
  RETURN grant_count;
END;
$$;

-- Converted: GRANT SELECT ON TABLE sales.customer_accounts TO reader -> GRANT SELECT ON VIEW SALES.CUSTOMER_ACCOUNTS TO ROLE READER.
-- Reason: SALES.CUSTOMER_ACCOUNTS is a view, so the Snowflake object type is VIEW. Snowflake grants object privileges to roles, and the privilege stays specific (no ALL, no PUBLIC).
GRANT SELECT ON VIEW SALES.CUSTOMER_ACCOUNTS TO ROLE READER;

-- Converted: GRANT SELECT ON TABLE sales.account_payments TO reader -> GRANT SELECT ON VIEW SALES.ACCOUNT_PAYMENTS TO ROLE READER.
-- Reason: SALES.ACCOUNT_PAYMENTS is a view, so the Snowflake object type is VIEW. Snowflake grants object privileges to roles, and the privilege stays specific (no ALL, no PUBLIC).
GRANT SELECT ON VIEW SALES.ACCOUNT_PAYMENTS TO ROLE READER;
